from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent.parent;SRC=ROOT/'source';I=json.loads((SRC/'icons.json').read_text())
def icon(n):return I[n]
def link(scene,text,cls=''):return f'<a class="{cls}" href="{scene}.html">{text}</a>'
def img(name,alt,cls=''):return f'<img class="{cls}" src="../assets/{name}.png" alt="{alt}">'
def button(text,scene=None,secondary=False):
 cls='button'+(' secondary' if secondary else '')
 return link(scene,text,cls) if scene else f'<button type="button" class="{cls}">{text}</button>'
def field(label,value='',full=False,type='text',help='',placeholder='',mobilefull=False):
 return f'<div class="field {"full" if full else ""} {"mobile-full" if mobilefull else ""}"><label>{label}</label><input type="{type}" value="{html.escape(value,quote=True)}" placeholder="{placeholder}" aria-label="{label}">{f"<span class=help>{help}</span>" if help else ""}</div>'
products=[dict(id='linen-shirt',name='The Everyday Linen Shirt',price='₹2,490',color='Oat',material='100% linen',sub='Relaxed fit · Oat'),dict(id='trousers',name='Tailored Straight Trouser',price='₹3,290',color='Ink',material='Linen blend',sub='Straight fit · Ink'),dict(id='cotton-dress',name='The Everyday Cotton Dress',price='₹3,990',color='Rust',material='100% cotton',sub='Easy fit · Rust')]
def header():return f'''<div class="announcement">Meet the new everyday collection</div><header class="header"><div class="wrap header-inner"><a class="menu-button" href="03-collection.html" aria-label="Open menu">{icon('Menu')}</a>{link('01-home-top','THREADLINE','wordmark')}<nav class="desktop-nav" aria-label="Primary">{link('03-collection','New')}{link('03-collection','Clothing')}{link('02-home-bottom','Collections')}{link('05-product-fit','Fit guide')}{link('02-home-bottom','About')}</nav><div class="utilities"><a class="utility" href="03-collection.html" aria-label="Search">{icon('Search')}</a><a class="utility account" href="12-profile.html" aria-label="Account">{icon('UserRound')}</a><a class="utility" href="07-cart.html" aria-label="Bag with two items">{icon('ShoppingBag')}<small>2</small></a></div></div></header>'''
def footer():return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div><div class="wordmark">THREADLINE</div><p>Considered clothing for your everyday.</p><p style="margin-top:14px;max-width:280px">Pieces to return to. Fits to feel like yourself in.</p></div><div><h4>Explore</h4>{link('03-collection','New arrivals')}{link('03-collection','Clothing')}{link('02-home-bottom','Collections')}</div><div><h4>Here to help</h4>{link('05-product-fit','Fit & size guide')}{link('06-product-outfit','Shipping & returns')}{link('14-order-detail','Order support')}</div><div><h4>Your account</h4>{link('10-sign-in','Sign in')}{link('13-orders','Your orders')}{link('15-addresses','Saved addresses')}</div></div><div class="footer-note"><span>© 2026 Threadline. All rights reserved.</span><span>Privacy · Terms · India / INR ₹</span></div></div></footer>'''
