def cards():
 out='<div class="product-grid">'
 for p in products:out+=f'''<article class="product-card"><div class="product-image">{link('04-product-main',img(p['id'],p['name']))}<button type="button" class="save" aria-label="Save {p['name']}">{icon('Heart')}</button></div><div class="product-info"><h3>{link('04-product-main',p['name'])}</h3><span class="price">{p['price']}</span></div><div class="subline">{p['sub']} · XS–XL</div><div class="mini-swatches" aria-label="Color"><i style="background:{'#cbb99b' if p['color']=='Oat' else '#363536' if p['color']=='Ink' else '#a85737'}"></i><span style="font-size:10px;color:var(--muted)">{p['color']}</span></div></article>'''
