def home_bottom():return header()+f'''<main><section class="wrap section"><div class="section-heading"><div><div class="eyebrow">FRESH PERSPECTIVES</div><h2 style="margin-top:12px">New arrivals</h2></div>{link('03-collection','Explore the edit '+icon('ArrowRight'),'text-link')}</div>{cards()}</section><section class="outfit-feature">{img('hero','The complete shirt and trouser outfit')}<div class="outfit-copy"><div class="eyebrow">BETTER TOGETHER, STILL YOURS</div><h2>One outfit.<br>Make it your own.</h2><p>An easy pairing for wherever the day takes you. Every piece, individually chosen.</p>'''+''.join(f'<a class="outfit-row" href="04-product-main.html"><div><strong>{p["name"]}</strong><p>{p["color"]} · {p["price"]}</p></div>{icon("ArrowRight")}</a>' for p in products[:2])+f'''</div></section><section class="wrap section fabric-feature">{img('linen-detail','A close-up of linen weave, cuff and stitching')}<div><div class="eyebrow">FEEL THE DIFFERENCE</div><h2>Good things<br>take a little care.</h2><p>Know the fabric. Understand the fit. Find the small details that make a piece feel like yours.</p>{link('05-product-fit','Explore fabric & care '+icon('ArrowRight'),'text-link')}</div></section>{services()}</main>{footer()}'''
