def order_detail():
 body=f'''<section class="account-card"><div class="card-head"><h2>Order #TL-1042</h2>{status(True)}</div><p>Placed on 22 October 2026 · 2 items</p><div class="delivery-timeline"><div class="timeline-step complete">Confirmed<p>22 Oct</p></div><div class="timeline-step complete">Processing<p>Current status</p></div><div class="timeline-step">Shipped<p>Not yet</p></div><div class="timeline-step">Delivered<p>Not yet</p></div></div></section><section class="account-card"><h2>The pieces you chose</h2>'''+''.join(f'<div class="detail-product">{img(p["id"],p["name"])}<div><h3>{p["name"]}</h3><p>{p["color"]} / M · Quantity 1</p></div><strong>{p["price"]}</strong></div>'for p in products[:2])+f'''</section><div class="detail-bottom"><section class="account-card"><h3>Delivery address</h3><p>Asha<br>12 Sample Lane<br>Bengaluru, Karnataka 560001<br>India</p><div style="margin-top:24px"><h3>Payment</h3><p>Online payment · Paid</p></div></section><section class="account-card"><h3>Order summary</h3><div class="summary-row"><span>Subtotal</span><span>₹5,780</span></div><div class="summary-row"><span>Shipping</span><span>₹100</span></div><div class="summary-row total"><span>Total paid</span><span>₹5,880</span></div></section></div><div class="inline-info">{icon('CircleHelp')}Need help with this order? Use the store's order-support contact.</div>'''
 return account('Every detail, in one place.','Your order and its latest available status.',body,'Orders')
def addresses():
 body=f'''<div class="address-grid"><section class="address-card selected"><div class="card-head"><h3>Home</h3><span class="status">Default</span></div><p><strong>Asha</strong><br>12 Sample Lane<br>Bengaluru, Karnataka 560001<br>India</p><div class="address-actions"><button type="button">Edit</button><button type="button">Delete</button></div></section><button class="address-card add-address" type="button">{icon('Plus')}<span>Add an address</span><small>For wherever the day takes you.</small></button></div><div class="inline-info">{icon('Info')}Your default address can be used at checkout. You can always choose a different one.</div>'''
 return account('Your saved addresses.','A little less to type next time.',body,'Addresses')
scenes=[('01-home-top','Homepage · first half',home_top,'Announcement, editorial hero, two CTAs and silhouette discovery.'),('02-home-bottom','Homepage · second half',home_bottom,'New arrivals, separately priced outfit, fabric story, service information and footer.'),('03-collection','Products / collection',collection,'Portrait merchandise cards with size/color/price discovery and restrained sorting.'),('04-product-main','Product detail · selection',product_main,'Gallery, price, named color, size, fit summary, quantity and add to bag.'),('05-product-fit','Product detail · fit & fabric',product_fit,'Garment measurements, selected M, unit context, fabric detail and care.'),('06-product-outfit','Product detail · continuation',product_outfit,'Complete the look with independently priced products and shipping/return information.'),('07-cart','Cart / bag',cart,'Editable line summary, quantity, subtotal and shared checkout entry.'),('08-checkout-address','Shared checkout · address',checkout_address,'Threadline branding with the existing shared two-step address/review structure.'),('09-checkout-review','Shared checkout · review & pay',checkout_review,'Shipping review, server quote summary and available Razorpay/COD presentation.'),('10-sign-in','Sign in',lambda:identity(False),'Canonical LetBuyy buyer identity with a clear Threadline destination.'),('11-sign-up','Create account',lambda:identity(True),'Canonical LetBuyy registration; no separate merchant-controlled credential form.'),('12-profile','Profile overview',profile,'Account details, recent orders, saved address and support entry.'),('13-orders','Order history',orders,'Linked store orders with clear state, amount and detail entry.'),('14-order-detail','Order detail',order_detail,'Actual-status pattern, ordered items, delivery address and payment summary.'),('15-addresses','Saved addresses',addresses,'Default address, add/edit affordances and checkout context.')]
meta=[]
for id,title,fn,description in scenes:
 body=fn();htmlpage=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · Threadline visual target</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"></head><body data-scene="{id}">{body}</body></html>'''
 (SRC/f'{id}.html').write_text(htmlpage);meta.append(dict(id=id,title=title,description=description,source=f'source/{id}.html'))
(ROOT/'scenes.json').write_text(json.dumps(meta,indent=2))
# Browsable exact sources, before final exported images exist.
(ROOT/'prototype-index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Threadline source mockups</title><style>body{font:17px/1.6 system-ui;margin:40px;background:#faf7f2;color:#241e1a}a{color:#713f35}li{margin:12px 0}</style><h1>Threadline · responsive mockup sources</h1><p>Visual-only fixture. No real authentication, order or payment is connected.</p><ol>'+''.join(f'<li><a href="{x["source"]}">{x["title"]}</a><br><small>{x["description"]}</small></li>'for x in meta)+'</ol></html>')
